    "Cihazın yayınladığı, yukarıdaki alanların kapsamadığı sensörler — bir kurutma makinesinin hava sıcaklığı ve kalan nemi, bir buzdolabının ikinci kapısı: sensor.*, binary_sensor.*, number.* varlıkları. Eklediğin sırayla, kendi adı ve birimiyle cihaz penceresinde görünürler.",
  "The top strip — hamburger, house name, weather — stays put while the rest of the dashboard scrolls under it. This device only.":
    "Üstteki şerit — menü, ev adı, hava durumu — sabit kalır, panonun geri kalanı altından kayar. Yalnızca bu cihazda.",
  "The watt sensor of the plug the unit sits under. With the threshold below, it is the one that says whether the unit is running: an air conditioner driven by a plug knows it better than its own thermostat.":
    "Ünitenin bağlı olduğu prizin watt sensörü. Aşağıdaki eşikle birlikte, ünitenin çalışıp çalışmadığını o söyler: prizle çalışan bir klima bunu kendi termostatından daha iyi bilir.",
  "There are ${quante} configured cameras that are not shown here now.":
    "Burada şu anda görünmeyen ${quante} yapılandırılmış kamera var.",
  "There is 1 configured camera that is not shown here now.":
    "Burada şu anda görünmeyen 1 yapılandırılmış kamera var.",
  "There is no reading for this load right now.": "Şu anda bu yük için bir okuma yok.",
  "They cost nothing at any hour, and the euros above are only on what it took from the grid.":
    "Hiçbir saatte bir şey tutmazlar; yukarıdaki tutarlar yalnızca şebekeden alınanı kapsar.",
  "They stay written here so you know they exist. The bell puts them back in the warning, if they are still silent.":
    "Var olduklarını bilesin diye burada yazılı kalırlar. Hâlâ sessizlerse zil onları uyarıya geri koyar.",
  "This dashboard's configuration is reserved for its administrator.":
    "Bu panonun yapılandırması yöneticisine ayrılmıştır.",
  "This entity is not present in this home.": "Bu varlık bu evde yok.",
  "This is an energy meter (kWh): it says how much it has consumed overall, not how much it is drawing right now. It is ignored here — it belongs in the “Total energy for history and Report” field.":
    "Bu bir enerji sayacı (kWh): toplamda ne kadar tükettiğini söyler, şu anda ne kadar çektiğini değil. Burada yok sayılır — yeri «Geçmiş ve rapor için toplam enerji» alanıdır.",
  "This sensor declares no unit of measurement: the card only shows W or kW sensors, and ignores this one.":
    "Bu sensör bir ölçü birimi bildirmiyor: kart yalnızca W veya kW sensörlerini gösterir, bunu yok sayar.",
  "This sensor measures in “${misura}”: the card only shows W or kW sensors, and ignores this one.":
    "Bu sensör «${misura}» ile ölçüyor: kart yalnızca W veya kW sensörlerini gösterir, bunu yok sayar.",
  "This weather entity has no forecast": "Bu hava durumu varlığı tahmin vermiyor",
  "To play": "Dinlenecekler",
  "Turn it off and the camera panel disappears from the Security page, leaving the alarm and the openings alone. The cameras stay configured: they come back by turning this on again.":
    "Kapat, kamera bölümü Güvenlik sayfasından kaybolsun; alarm ve açıklıklar yerinde kalır. Kameralar yapılandırılmış kalır: burayı yeniden açınca geri gelirler.",
  "Turn it off if this house has no panels: the Energy page stops showing production and self-sufficiency, and keeps consumption, costs and time bands. The entities written below stay where they are.":
    "Bu evde panel yoksa kapat: Enerji sayfası üretimi ve öz yeterliliği göstermeyi bırakır, tüketimi, maliyetleri ve zaman dilimlerini tutar. Aşağıya yazılan varlıklar oldukları yerde kalır.",
  "Vehicle kind": "Araç türü",
  Vehicles: "Araçlar",
  "Vertical swing": "Dikey kanatlar",
  "Water softener": "Su yumuşatıcı",
  "What lights the card up": "Kartı ne yakar",
  "One tap picks it: while that entity is on, the appliance card and its Home tile take on a colour so you notice them. None is picked by default — a fridge opened to get the milk is not a fault — but the garage freezer door, or the washing machine finishing, belong here.":
    "Tek dokunuş seçer: o varlık açık olduğu sürece cihazın kartı ve Ana ekrandaki karosu fark edilsin diye renk alır. Öntanımlı olarak hiçbiri seçili değildir — süt almak için açılan bir buzdolabı arıza değildir — ama garajdaki derin dondurucunun kapağı ya da çamaşır makinesinin bitişi buraya girer.",
  "What to show in the window": "Pencerede ne görünsün",
  "Where it is configured": "Nerede ayarlanır",
  "Where we are": "Neredeyiz",
  "Which band it draws in": "Hangi dilimde tüketiyor",
  "Which rooms show up on Home, with the temperature and how many things are on: one tap takes you into the room. As many as you like; none ticked means no block at all.":
    "Ana ekranda hangi odalar görünsün: sıcaklıkla ve kaç şeyin açık olduğuyla birlikte; bir dokunuş seni odanın içine götürür. İstediğin kadar; hiçbiri işaretli değilse blok hiç çıkmaz.",
  "Windows and shutters": "Pencereler ve panjurlar",
  "Zones and entry points of the panel": "Panelin bölgeleri ve girişleri",
  "at least": "en az",
  "climate first": "klima önceden",
