  "tap the option to set": "ayarlamak için seçeneğe dokunun",
  "this entity is read-only, it can't be switched on. The switch needs a switch, a socket or a fan.":
    "bu varlık yalnızca okunur, açılmaz. Anahtar için bir switch, bir priz ya da bir fan gerekir.",
  "this isn't a Home Assistant entity. It's written domain.name, for example switch.ventola_inverter.":
    "bu bir Home Assistant varlığı değil. alan.ad şeklinde yazılır, örneğin switch.ventola_inverter.",
  "this menu does not list its options": "bu menü seçeneklerini bildirmiyor",
