    "Deprem · Hava · Yıldırım · Polen · Uçuşlar",
  "Earthquakes, civil protection warnings, lightning, pollen, thermal comfort and flights overhead: for each one pick the sensor its integration already brought into Home Assistant. No field is required and each one is enough on its own: the page shows only the sources you have. The dashboard calls no service, it reads what is there.":
    "Depremler, sivil savunma uyarıları, yıldırım, polen, ısıl konfor ve tepedeki uçuşlar: her biri için entegrasyonunun zaten Home Assistant'a getirdiği sensörü seçin. Hiçbir alan zorunlu değil ve her biri tek başına yeter: sayfa yalnızca sahip olduğunuz kaynakları gösterir. Panel hiçbir servisi çağırmaz, olanı okur.",
