  Error: "Hata",
  "Estimated time": "Tahmini süre",
  Events: "Olaylar",
  "Every area is a Home Assistant panel of its own, with its own arming modes. The one marked “on the page now” is what the dial and the keypad are commanding: the eye beside another one brings it on screen in its place.":
    "Her bölge kendi kurulum modlarına sahip ayrı bir Home Assistant panelidir. «şu an sayfada» yazan, kadranın ve tuş takımının komut verdiğidir: bir başkasının yanındaki göz onu onun yerine ekrana getirir.",
  "Every field is optional: the card automatically shows what is available. Start, duration, energy and cost of the last cycle are computed automatically from power transitions unless you provide dedicated entities.":
    "Bütün alanlar isteğe bağlıdır: kart, elde olanı kendiliğinden gösterir. Son programın başlangıcı, süresi, enerjisi ve maliyeti, ayrı varlıklar vermediğin sürece güç değişimlerinden otomatik hesaplanır.",
  "Every filled box must be a cover.* or switch.* entity.":
    "Doldurulan her kutu bir cover.* veya switch.* varlığı olmalıdır.",
  "Every load below is a circle of the Energy flow, under Home, in the order of this list. What you write here is what the flow shows, and the devices you file under it are the ones that appear when you tap the circle.":
    "Aşağıdaki her yük, Ev'in altında Enerji akışının bir dairesidir ve sıralaması bu listeye göredir. Buraya yazdığın şey akışta görünür; altına yerleştirdiğin cihazlar da daireye dokununca çıkanlardır.",
  "Every plant has its own meter, its own solar, its own battery and its own loads. The fields below belong to the selected plant: adding one starts from scratch and leaves what you already configured alone.":
    "Her tesisin kendi sayacı, kendi güneş panelleri, kendi bataryası ve kendi yükleri vardır. Aşağıdaki alanlar seçili tesise aittir: yeni bir tane eklemek sıfırdan başlar ve daha önce ayarladıklarına dokunmaz.",
  "Every plant has its own thirteen fields. The one marked “on the page now” is what the Solar thermal page and the Home tile are showing: the eye beside another one brings it on screen in its place.":
    "Her tesisin kendi on üç alanı var. «şu an sayfada» yazan, Güneş Enerjisi sayfasının ve Ana ekrandaki karonun gösterdiğidir: bir başkasının yanındaki göz onu onun yerine ekrana getirir.",
  "Everything is here: the window's card shows its room's humidity and says to open as soon as it goes above the threshold.":
    "Her şey tamam: pencerenin kartı odasının nemini gösterir ve eşiği aşar aşmaz açmayı söyler.",
  "Everything off": "Hepsi kapalı",
  "Everything on the repository": "Depodaki her şey",
  "Everything the dashboard can do, and whether it shows. The same switch is also at the top of each section's own tab: here they are all together, so you can see what exists without opening them one by one.":
    "Panonun yapabildiği her şey ve görünüp görünmediği. Aynı anahtar her bölümün kendi sekmesinin üstünde de var: burada hepsi bir arada, tek tek açmadan neler olduğunu görebilirsiniz.",
