  "Fireplace pump": "Şömine pompası",
  "First configure the circles connected to Home. Each circle can use a direct power sensor or automatically sum every child of a load group. Then create the appliances inside each group. Empty or disabled nodes are not forced into the flow.":
    "Önce Ev'e bağlı daireleri yapılandır. Her daire doğrudan bir güç sensörü kullanabilir ya da grubundaki tüm yükleri kendiliğinden toplayabilir. Sonra her grubun içine cihazları oluştur. Boş ya da kapalı düğümler akışa zorlanmaz.",
  "First select your lights in the Lights step (or wizard).":
    "Önce Işıklar adımında (ya da sihirbazda) ışıklarınızı seçin.",
  Fixed: "Sabit",
  "Fixed cycle duration (minutes)": "Sabit program süresi (dakika)",
  "Flap opened": "Kapak açıldı",
  "Flightradar24 exposes “current in area”: the count, with the list of flights in the attributes.":
    "Flightradar24 “current in area” verir: sayı, özniteliklerde uçuş listesiyle birlikte.",
  "Flights in the area": "Bölgedeki uçuşlar",
  "Flights overhead": "Tepedeki uçuşlar",
  "Flip the direction (ON = closed)": "Yönü ters çevir (ON = kapalı)",
