  Flow: "Gidiş",
  "Flow temperature": "Gidiş sıcaklığı",
  "Flow · Return · Pressure": "Gidiş · Dönüş · Basınç",
  "Flue extractor fan": "Baca aspiratörü",
  "Flue gas": "Baca gazı",
  "Flue gas fan": "Baca gazı fanı",
  "Flue gas temperature": "Baca gazı sıcaklığı",
  "Followed train": "Takip edilen tren",
  Food: "Mama",
  "Food level": "Mama seviyesi",
  "Food running low": "Mama tükeniyor",
  "For each item enter": "Her öğe için şunu girin:",
  "For every source, Total energy meter is the cumulative Recorder source (normally state_class: total_increasing). It is not a period value: day, month and year are calculated as final Recorder sum minus initial Recorder sum, so meter resets are preserved. Period sensors are optional current-period overrides.":
    "Her kaynak için toplam enerji sayacı, birikimli Recorder kaynağıdır (genellikle state_class: total_increasing). Bu bir dönem değeri değildir: gün, ay ve yıl, Recorder'ın son toplamından ilk toplamı çıkarılarak hesaplanır; böylece sayaç sıfırlamaları korunur. Dönem sensörleri, içinde bulunulan dönem için isteğe bağlı bir üstünlemedir.",
  "For fridge and freezer: shows the temperature strip instead of the power bar.":
    "Buzdolabı ve derin dondurucu için: güç çubuğu yerine sıcaklık şeridini gösterir.",
  "For lights you only want to see, with no accidental taps: the row stays where it is, the button stops responding.":
    "Yalnızca görmek istediğiniz ışıklar için, yanlışlıkla dokunma olmadan: satır yerinde kalır, düğme yanıt vermez.",
  "For sockets that must not be switched off: the fridge, the modem, the freezer. The row stays where it is, the button stops responding.":
    "Kapatılmaması gereken prizler için: buzdolabı, modem, dondurucu. Satır yerinde kalır, düğme yanıt vermeyi bırakır.",
  "For this window only: resting at this percentage or below counts as closed. Empty, the house threshold at the top applies.":
    "Yalnızca bu pencere için: bu yüzdede veya altında durmak kapalı sayılır. Boşsa üstteki ev eşiği geçerlidir.",
  "For this window only: when its room's humidity goes above this level, the card says to open it to air out. Empty, the house threshold at the top applies; zero turns the advice off on this window.":
    "Yalnızca bu pencere için: odasının nemi bu düzeyi aşınca kart havalandırmak için açmayı söyler. Boşsa üstte yazılı ev eşiği geçerlidir; sıfır bu pencerede öneriyi kapatır.",
  "For those without a panel: an alarm built with ESPHome, with scripts or with a list of modes. Each button below shows up in the Security section and on the Home tile, next to the panel's own — and when there is no panel, in their place.":
    "Panel'i olmayanlar için: ESPHome ile, betiklerle ya da bir mod listesiyle kurulmuş bir alarm. Aşağıdaki her düğme Güvenlik bölümünde ve Ana sayfa kartında, panelinkilerin yanında çıkar — panel yoksa onların yerine.",
  "For what recharges instead of being replaced: the wall tablet, a power bank. The two entities are number.* or input_number.*, the ones the device exposes to say where it starts again and where it stops. Leave them empty and this stays a battery like the others.":
    "Değiştirilmek yerine şarj edilen şeyler için: duvardaki tablet, bir powerbank. İki varlık number.* ya da input_number.*, yani cihazın nerede yeniden başladığını ve nerede durduğunu söylemek için sunduğu varlıklar. Boş bırakırsan bu da diğerleri gibi bir pil olarak kalır.",
  "Force (ignore rain)": "Zorla (yağmuru yok say)",
  Forest: "Orman",
  "Found next to the appliance — one tap adds them:":
    "Cihazın yanında bulundu — bir dokunuş onları ekler:",
