  "Fountain filter": "Su pınarı filtresi",
  "Four sensors of your choosing: the ones you actually read to decide, not a house average. The typical one is outdoors, the one you go by for the indoor units. The unit comes from Home Assistant, and a sensor you do not name is a pill that does not show up.":
    "Senin seçtiğin dört sensör: karar vermek için gerçekten baktıkların, evin ortalaması değil. Tipik olanı dışarıdaki, iç üniteleri ona göre ayarladığın. Birimi Home Assistant söyler, ve belirtmediğin bir sensör görünmeyen bir kart demektir.",
