  Good: "İyi",
  "Good up to the first, fair up to the second, poor up to the third, bad beyond. The defaults are the norms: the European index bands for particulates and gases, EN 16798-1 for CO₂, the WHO guidelines for monoxide. Change them only if you know why.":
    "Birinciye kadar iyi, ikinciye kadar orta, üçüncüye kadar kötü, ötesi çok kötü. Varsayılanlar normlardır: parçacıklar ve gazlar için Avrupa indeksi bantları, CO₂ için EN 16798-1, karbonmonoksit için DSÖ kılavuzları. Nedenini biliyorsan değiştir.",
