  Idle: "Boşta",
  "If below (%)": "Şunun altındaysa (%)",
  "If the collections live in one place, put it here: a calendar.* with one event per collection, or a sensor.* carrying the list of upcoming collections in its attributes. Each entry becomes a row, with the material guessed from its name.":
    "Toplamalar tek bir yerde duruyorsa buraya yaz: her toplama için bir etkinliği olan bir calendar.* ya da yaklaşan toplamaların listesini özniteliklerinde taşıyan bir sensor.*. Her kayıt bir satır olur ve tür adından tahmin edilir.",
  "If the panel splits the house into areas — day zone and night zone, house and workshop — add the second one here: the one you have now moves into the list exactly as it is, and the page grows a row to switch between them, each with its own state.":
    "Panel evi bölgelere ayırıyorsa — gündüz ve gece bölgesi, ev ve atölye — ikincisini buraya ekle: şu an sahip olduğun olduğu gibi listeye geçer ve sayfada, her biri kendi durumuyla, aralarında geçiş için bir sıra belirir.",
  "If you have one, this is enough: it declares state, temperature and target itself.":
    "Varsa bu yeter: durumu, sıcaklığı ve hedefi kendisi bildirir.",
  "If you have two solar plants — two roofs, two tanks — add the second one here: the one you have now moves into the list exactly as it is, and the page grows a row to switch between them.":
    "İki güneş tesisin varsa — iki çatı, iki depo — ikincisini buraya ekle: şu an sahip olduğun olduğu gibi listeye geçer ve sayfada aralarında geçiş için bir sıra belirir.",
  "If you run go2rtc or Frigate, put this line under “streams:” in their file:":
    "go2rtc ya da Frigate kullanıyorsanız bu satırı onların dosyasında «streams:» altına koyun:",
