  "Off / Closed (off)": "Kapalı (off)",
  "Off, the weather entity above is enough: temperature, humidity and wind come from it.":
    "Kapalıyken yukarıdaki weather varlığı yeter: sıcaklık, nem ve rüzgar ondan okunur.",
