  "On / Active / Open (on)": "Açık / Etkin (on)",
  "On Home": "Ana sayfada",
  "On battery": "Aküde",
  "On battery · ${carica}%": "Aküde · %${carica}",
  "On cards show the room temperature big (target below)":
    "Kartlarda oda sıcaklığını büyük göster (hedef altta)",
  "On mains": "Şebekede",
  "On time": "Zamanında",
  "On which page": "Hangi sayfada",
  "On, the radar plays the last hour of rain: you see which way the front is moving, not only where it is now. That is six frames instead of one, so six rounds of tiles: turn it off on a slow connection, or if you prefer a single image.":
    "Açıkken radar son bir saatlik yağışı oynatır: cephenin nereye gittiği görülür, yalnızca şu an nerede olduğu değil. Bu, bir yerine altı karedir, yani altı tur döşeme: bağlantı yavaşsa ya da tek bir görüntü yetiyorsa kapatın.",
  "On/off control": "Aç/kapat kumandası",
  "On/off · Brightness · Colour": "Aç/kapat · Parlaklık · Renk",
  "On/off · Consumption · Room by room": "Açma/kapama · Tüketim · Oda oda",
  "One bin per material, and for each the sensor that says when the collection comes: the page answers the evening question — what do I put out tonight — and the Home tile lights up the day before. Whoever has a single calendar, with one event per collection, puts it in the box at the bottom.":
    "Her malzeme için bir kutu ve her biri için toplamanın ne zaman geleceğini söyleyen sensör: sayfa akşam sorusuna — bu gece ne çıkarayım — yanıt verir ve Ana Sayfa karosu bir gün önce yanar. Her toplama için bir etkinliği olan tek bir takvimi olan, onu en alttaki kutuya koyar.",
  "One room at a time · Scenes · Sensors": "Tek seferde bir oda · Sahneler · Sensörler",
  "One single tile": "Tek bir karo",
  "One step, and you will never be asked again: open github.com/login/device and type this code.":
    "Tek bir adım, ve bir daha asla sorulmayacak: github.com/login/device adresini aç ve bu kodu gir.",
  "One tile per plant": "Tesis başına bir tane",
  "One window can carry all three: fill in the boxes you have, the box tells the type.":
    "Tek bir pencerede üçü birden olabilir: elindeki kutuları doldur, türü kutunun kendisi söyler.",
  "Only daily sensors or Recorder deltas from cumulative total meters are counted. Lifetime values are never added directly.":
    "Yalnızca günlük sensörler ya da birikimli toplam sayaçların Recorder farkları sayılır. Toplam sayaç değerleri asla doğrudan toplanmaz.",
  "Only if you already have a helper measuring the period. Without one, the period comes from the total meter.":
    "Yalnızca dönemi ölçen bir helper'ın zaten varsa. Yoksa dönem, toplam sayaçtan gelir.",
  "Only needed when the shutter is driven by two relays — one that sends it up, one that sends it down — like a Shelly left in switch mode: then “Close” switches this one on, and “Stop” switches both off. With a real cover.* leave it empty.":
    "Yalnızca panjur iki röleyle sürülüyorsa gerekir — biri yukarı, biri aşağı gönderir — anahtar modunda bırakılmış bir Shelly gibi: o zaman «Kapat» bunu açar, «Durdur» ikisini de kapatır. Gerçek bir cover.* varsa boş bırak.",
  "Only rooms containing a light are shown. Edit opens all light fields, not a browser prompt. The pills say what each light can do — RGB, tunable white, dimmer or plain on/off — and that is what drives the controls in the popup.":
    "Yalnızca ışık içeren odalar gösterilir. Düzenle, tarayıcı penceresi değil ışığın tüm alanlarını açar. Rozetler her ışığın neler yapabildiğini söyler — RGB, ayarlanabilir beyaz, kısıcı ya da düz aç/kapat — ve penceredeki kumandalar buna göre belirlenir.",
  "Only the modes the panel actually accepts are listed. Removing one hides it from the section and changes nothing about what the panel can do; disarm always stays.":
    "Burada yalnızca panelin gerçekten kabul ettiği kipler var. Birini kaldırmak onu bölümden gizler, panelin yapabildiklerini değiştirmez; devre dışı bırakma her zaman kalır.",
  "Only with the soil below (%)": "Yalnızca toprak şunun altındayken (%)",
  Open: "Açık",
  "Open (as before)": "Aç (eskisi gibi)",
  "Open the menu": "Menüyü aç",
  "⚪ Empty section — add an entity below to show it":
    "⚪ Boş bölüm — göstermek için aşağıya bir varlık ekleyin",
  "You haven't saved": "Kaydetmediniz",
  "You entered entities in this section without saving them. If you leave now, they will be lost.":
    "Bu bölüme varlıklar girdiniz ama kaydetmediniz. Şimdi çıkarsanız kaybolacaklar.",
  "Save and continue": "Kaydet ve devam et",
  "Leave without saving": "Kaydetmeden çık",
  "Stay here": "Burada kal",
  "Nobody home": "Evde kimse yok",
  "Big buttons: a dashboard action or any entity (a scene, a script, a button). For each one the name on the tablet, the line below and the drawing.":
    "Büyük düğmeler: panodan bir eylem veya herhangi bir varlık (bir sahne, bir betik, bir düğme). Her biri için tabletteki ad, alttaki satır ve çizim.",
  "Full config": "Tüm yapılandırma",
  "On, a light added to the room in the source dashboard shows up by itself. Off, the slots are chosen here: any entity or action, with the name and drawing you want.":
    "Açık: kaynak panoda odaya eklenen bir ışık kendiliğinden görünür. Kapalı: yerler burada seçilir — istediğiniz ad ve çizimle herhangi bir varlık veya eylem.",
  "Slots of your own: in each one any Home Assistant entity — a light, a socket, a lock, a sensor — or a dashboard action, with the name and drawing you want.":
    "Tamamen size ait yerler: her birinde herhangi bir Home Assistant varlığı — bir ışık, bir priz, bir kilit, bir sensör — veya panodan bir eylem, istediğiniz ad ve çizimle.",
  "A dehumidifier is not a thermostat: pick its humidifier entity and the Climate page gives it a card of its own, with the current humidity, the target, the modes, the fan and the tank-full warning. The other fields fill themselves in when you save.":
    "Nem alıcı bir termostat değildir: humidifier varlığını seç, İklim sayfası ona mevcut nem, hedef, modlar, fan ve dolu tank uyarısıyla kendi kartını verir. Diğer alanlar kaydederken kendiliğinden dolar.",
  "Add a dehumidifier": "Nem alıcı ekle",
  "Alongside (filled in automatically on save)": "Yanında (kaydederken otomatik doldurulur)",
  Baby: "Bebek",
