  Shutters: "Panjurlar",
  "Shutters and curtains show up on the 🪟 Windows page, grouped by floor and room. Every row accepts a cover.* entity — with position and percentages — or a switch.* relay: one when switching it on keeps the shutter up, two when one relay sends it up and another sends it down, like a Shelly in switch mode. When the window opens by hand — shutters, blinds, a handle — leave the command boxes empty and fill in the contact sensor alone: the card still draws it and says whether it is open.":
    "Panjurlar ve perdeler 🪟 Pencereler sayfasında, kat ve odaya göre gruplanmış olarak görünür. Her satır bir cover.* varlığı — konum ve yüzdelerle — ya da bir switch.* rölesi kabul eder: açıldığında panjur yukarıda kalıyorsa bir tane, biri yukarı diğeri aşağı gönderiyorsa iki tane — anahtar modundaki bir Shelly gibi. Pencere elle açılıyorsa — kepenk, panjur, bir kol — komut kutularını boş bırak ve yalnızca açılma sensörünü doldur: kart yine çizilir ve açık olup olmadığını söyler.",
  "Shutters · Curtains · Contact sensors": "Panjurlar · Perdeler · Açılma sensörleri",
