  "Time to buy more": "Yenisini alma zamanı",
  "Buy more below": "Şunun altında yenisini al",
  "and nobody is home": "ve evde kimse yok",
  "Sensor entity": "Sensör varlığı",
  "Until you pick the entity this meter is nowhere: not on the page, not on the Home tile.":
    "Varlığı seçmediğin sürece bu sayaç hiçbir yerde yoktur: ne sayfada, ne de ana ekrandaki kartta.",
  "Meters give today, yesterday and the month. Flow above zero for three hours without stopping is a leak, and the page says so in red. Pressure has its ideal range, and the softener salt is counted in days.":
    "Sayaçlar bugünü, dünü ve ayı verir. Üç saat boyunca durmadan sıfırın üzerinde kalan akış bir sızıntıdır ve sayfa bunu kırmızıyla söyler. Basıncın ideal aralığı vardır, yumuşatıcının tuzu ise gün olarak sayılır.",
  "The meters of the house: water, gas, and what the plumbing says. Each row is a sensor — the entity, the name you want, the drawing and what it measures — and the Water and gas page shows today, yesterday and the month, the pressure within its range, and water that never stops flowing.":
    "Evin sayaçları: su, gaz ve tesisatın söyledikleri. Her satır bir sensördür — varlık, istediğin ad, çizim ve neyi ölçtüğü — ve Su ve gaz sayfası bugünü, dünü ve ayı, aralığındaki basıncı ve hiç durmadan akan suyu gösterir.",
  "Ideal from (bar)": "İdeal alt sınır (bar)",
  "Ideal up to (bar)": "İdeal üst sınır (bar)",
  "Yesterday ${quanto}": "Dün ${quanto}",
  "The meter that counts (total or total_increasing), or the pressure, flow or salt sensor.":
    "Sayan sayaç (total veya total_increasing) ya da basınç, akış veya tuz sensörü.",
  "Last month ${quanto}": "Geçen ay ${quanto}",
  "On the bill it is the conversion coefficient: about 10.7 for methane. It lets gas and electricity be compared in the same unit.":
    "Faturada dönüşüm katsayısıdır: metan için yaklaşık 10,7. Gazı ve elektriği aynı birimde karşılaştırmayı sağlar.",
  "kWh per m³ (from the bill)": "m³ başına kWh (faturadan)",
  "The range a home's water should stay in: 2 to 4 bar for almost all of them. Outside it, the page turns amber.":
    "Evdeki suyun kalması gereken aralık: neredeyse hepsi için 2 ile 4 bar. Dışına çıkınca sayfa kehribar rengine döner.",
  "Never still in 24 hours": "24 saattir hiç durmadı",
  "In the same unit as the sensor: percent or kilograms. The page counts the days left, at the pace of the last few days.":
    "Sensörle aynı birimde: yüzde veya kilogram. Sayfa, son günlerin hızıyla kalan günleri sayar.",
