  "Take the ${quante} soil sensors Home Assistant found":
    "Home Assistant'ın bulduğu ${quante} toprak sensörünü al",
  "The plants at home, one per row: the soil moisture sensor, the name, the drawing, and the temperature if there is one. The Plant care page says which need watering, which are waiting for rain and when the others will be due.":
    "Evdeki bitkiler, her satırda bir tane: toprak nemi sensörü, ad, çizim ve varsa sıcaklık. Bitkiler sayfası hangilerinin sulanması gerektiğini, hangilerinin yağmur beklediğini ve diğerlerinin sırasının ne zaman geleceğini söyler.",
  "The rain will see to it": "Yağmur halleder",
