  "The group is optional: actions with the same group sit together on Home, under a title that says how many are on and closes with a tap. Without groups it stays a single row.":
    "Grup isteğe bağlıdır: aynı gruptaki işlemler Ana sayfada bir arada durur; kaç tanesinin açık olduğunu söyleyen ve bir dokunuşla kapanan bir başlığın altında. Grup yoksa tek sıra kalır.",
