  "shutters open": "panjur açık",
  "Under the weather, open doors and open windows are two pills. By default the class Home Assistant gives the contact decides; pick here when it is not the right one.":
    "Hava durumunun altında açık kapılar ve açık pencereler iki ayrı hap olur. Varsayılan olarak Home Assistant'ın kontağa verdiği sınıf karar verir; doğru değilse burada seç.",
  "If the camera already has its own integration in Home Assistant — Reolink, Tapo, Hikvision — the entity is already there: pick it in the field above, and the video goes through it.":
    "Kameranın Home Assistant'ta zaten kendi entegrasyonu varsa — Reolink, Tapo, Hikvision — varlık da zaten vardır: onu yukarıdaki alanda seçin, video onun üzerinden gelir.",
  "The stream name only works with the dashboard opened outside Home Assistant: in here it cannot be reached, and the camera goes through its entity.":
    "Akış adı yalnızca pano Home Assistant dışında açıldığında işe yarar: buradan ona ulaşılamaz, kamera kendi varlığı üzerinden gelir.",
  "HLS: skipped, Home Assistant declares no stream for this camera":
    "HLS: atlandı, Home Assistant bu kamera için bir akış bildirmiyor",
