  health: "sağlık",
  "ideal below ${soglia}": "ideal: ${soglia} altı",
  "In Ah, Wh or kWh. Left empty, it is worked out from the charge and the capacity.":
    "Ah, Wh veya kWh cinsinden. Boş bırakılırsa şarj ve kapasiteden hesaplanır.",
  "It recognises JK, JBD and Daly BMS and Huawei LUNA2000 batteries from their entity names and groups them by prefix. It puts them here as rows, once: from then on they are yours.":
    "JK, JBD ve Daly BMS'lerini ve Huawei LUNA2000 bataryalarını varlık adlarından tanır ve öneke göre gruplar. Onları buraya bir kez satır olarak ekler: sonrasında sizindir.",
  "Optional. A battery that talks through the inverter — like the Huawei LUNA2000 with the Huawei Solar integration — has no BMS to choose: state of charge, power and energy go in Energy, “Flows & entities” tab, in the “Battery · charge” and “Battery · discharge” boxes. This tab is only for seeing the packs, or the modules, one by one.":
    "İsteğe bağlı. İnvertör üzerinden konuşan bir batarya — Huawei Solar entegrasyonuyla Huawei LUNA2000 gibi — için seçilecek bir BMS yoktur: şarj durumu, güç ve enerji Enerji bölümünde, «Akışlar ve varlıklar» sekmesinde, «Battery · charge» ve «Battery · discharge» kutularına girilir. Bu sekme yalnızca paketleri ya da modülleri tek tek görmek içindir.",
  "max ${cifre(pacco.massima.volt, 3)} V · cell ${pacco.massima.numero}":
    "maks ${cifre(pacco.massima.volt, 3)} V · hücre ${pacco.massima.numero}",
  "min ${cifre(pacco.minima.volt, 3)} V · cell ${pacco.minima.numero}":
    "min ${cifre(pacco.minima.volt, 3)} V · hücre ${pacco.minima.numero}",
  "MOS temperature": "MOS sıcaklığı",
  "needs balancing": "dengelenmeli",
  "Needs balancing": "Dengelenmeli",
  "Needs balancing above (mV)": "Şunun üstünde dengelenmeli (mV)",
  "New pack": "Yeni paket",
  "No battery pack": "Batarya paketi yok",
  "No battery pack configured": "Yapılandırılmış batarya paketi yok",
  "No cells found": "Hücre bulunamadı",
  "No pack answering": "Hiçbir paket yanıt vermiyor",
  "No reading": "Okuma yok",
  "One cell voltage per line, in cell order. You can paste them all at once, commas work too; “Find the cells” takes them from Home Assistant using the prefix of the pack's other entities.":
    "Her satıra bir hücre gerilimi, hücre sırasıyla. Hepsini bir kerede yapıştırabilirsiniz, virgülle de ayrılabilir; “Hücreleri bul” onları paketin diğer varlıklarının önekiyle Home Assistant'tan alır.",
  "Optional: if the BMS does not publish it, the imbalance is worked out from the cells.":
    "İsteğe bağlı: BMS yayınlamıyorsa dengesizlik hücrelerden hesaplanır.",
  "Other BMS": "Diğer BMS",
  "Pack 1": "Paket 1",
  "Pack saved": "Paket kaydedildi",
  "Current sign": "Akımın işareti",
  "Positive when charging (JK, JBD, Daly)": "Şarjda pozitif (JK, JBD, Daly)",
  "Negative when charging": "Şarjda negatif",
  "With the sign the BMS uses: if it writes it negative while charging, pick that in “Current sign”.":
    "BMS'nin kullandığı işaretle: şarj ederken negatif yazıyorsa bunu «Akımın işareti» içinde seçin.",
  "If the page says “Discharging” while the battery is charging, your BMS writes the current the other way round: pick “Negative when charging”.":
    "Batarya şarj olurken sayfa «Deşarj oluyor» diyorsa BMS'niz akımı ters yazıyor: «Şarjda negatif» seçin.",
  "Remaining energy": "Kalan enerji",
  "Save pack": "Paketi kaydet",
  "State of charge (SoC)": "Şarj durumu (SoC)",
  "State of health (SoH)": "Sağlık durumu (SoH)",
  "Take the ${quanti} packs Home Assistant found": "Home Assistant'ın bulduğu ${quanti} paketi al",
  "The pack's charge percentage: without it the pack does not show.":
    "Paketin şarj yüzdesi: o olmadan paket görünmez.",
  "The storage packs and their BMS: they show in the Batteries tab of Energy and on the Battery storage tile in Home. One pack per row: its entity is the state of charge, and inside are the others — health, voltages, currents, temperatures, cycles, capacity and every single cell.":
    "Depolamanın paketleri ve BMS'leri: Enerji'nin Bataryalar sekmesinde ve Ana sayfadaki Batarya depolama kutucuğunda görünürler. Satır başına bir paket: varlığı şarj durumudur, içinde diğerleri vardır — sağlık, gerilimler, akımlar, sıcaklıklar, döngüler, kapasite ve her bir hücre.",
  "to the house": "eve doğru",
  "Unit of a hand-written capacity": "Elle yazılan kapasitenin birimi",
  "Unnamed pack": "Adsız paket",
  "Until you pick the state of charge this pack is nowhere: not in Energy, not on the Home tile.":
    "Şarj durumunu seçene kadar bu paket hiçbir yerde görünmez: ne Enerji'de ne de Ana sayfadaki kutucukta.",
  "When the highest and lowest cells are further apart than this, the pack says “Needs balancing” and the Home tile asks for attention.":
    "En yüksek ve en düşük hücre bundan daha fazla ayrıldığında paket “Dengelenmeli” der ve Ana sayfadaki kutucuk dikkat ister.",
