  "Seconds, minutes or hh:mm. Empty: uses the “Program duration”.":
    "Saniye, dakika veya ss:dd. Boş: “Program süresi” kullanılır.",
  "Seconds, minutes, hh:mm or the end time. Empty: uses the “Remaining time”.":
    "Saniye, dakika, ss:dd veya bitiş saati. Boş: “Kalan süre” kullanılır.",
  "started at ${partita}": "başlangıç ${partita}",
  "The controls show up when cooking starts": "Kontroller pişirme başladığında görünür",
  "The entity_id given to services that do not name one. Empty: the cooking status.":
    "Kendi entity_id'sini yazmayan servislere verilen entity_id. Boş: pişirme durumu.",
  "The rest of the kitchen": "Mutfağın geri kalanı",
  "The temperature sensor.": "Sıcaklık sensörü.",
  "The timer is stopped until it resumes": "Zamanlayıcı devam edene kadar durdu",
  "Time and temperature set: it only needs starting":
    "Süre ve sıcaklık seçildi: yalnızca başlatmak kaldı",
  "Total time": "Toplam süre",
  "under a minute": "bir dakikadan az",
  "What the “Cooking” entry of Appliances reads and presses. A control is an entity (button, switch, number, script) or a service with its parameters: philips_airfryer.adjust_time time=60 method=add. A button only shows up when its field is filled in, and only if it answers.":
    "Cihazlar'daki “Pişirme” girişinin okuduğu ve bastığı şeyler. Bir kontrol bir varlıktır (button, switch, number, script) ya da parametreleriyle bir servistir: philips_airfryer.adjust_time time=60 method=add. Bir düğme yalnızca alanı doluysa ve yanıt veriyorsa görünür.",
  "Storage battery": "Depolama bataryası",
  "💾 Stove saved": "💾 Soba kaydedildi",
  "A fan, a number or a select. Without it, the thermostat's fan modes are used, if it has any.":
    "Bir fan, number ya da select. Yoksa, varsa termostatın fan modları kullanılır.",
  "A gas, pellet or wood boiler: flow, return, pressure, combustion.":
    "Gazlı, peletli ya da odunlu kazan: gidiş, dönüş, basınç, yanma.",
  "A number or a select, 1 to 5 or P1 to P5: on the page it becomes the dots with minus and plus.":
    "Bir number ya da select, 1'den 5'e veya P1'den P5'e: sayfada eksi ve artılı noktalara dönüşür.",
  "A pellet stove in a room: the flame, the power, the fan and the hopper. More than one, too.":
    "Bir odadaki pelet sobası: alev, güç, fan ve depo. Birden fazlası da olur.",
  "A sensor with the alarm text or a binary_sensor: when it trips, the page shows the red banner with its words.":
    "Alarm metnini veren bir sensör ya da binary_sensor: devreye girince sayfa onun sözleriyle kırmızı şeridi gösterir.",
  "Add stove": "Soba ekle",
  "An electric water heater, fed by the PV plant or not.":
    "Güneş panelinden beslensin ya da beslenmesin, elektrikli bir termosifon.",
  "As a percentage or in kg, like the boiler's; or a binary_sensor that turns on when the pellet is running low.":
    "Kazandaki gibi yüzde ya da kg olarak; veya pelet azaldığında açılan bir binary_sensor.",
  "Brazier cleaning": "Yanma haznesi temizliği",
  "Check the stove's display.": "Sobanın ekranına bak.",
  "Flame · Power · Pellet": "Alev · Güç · Pelet",
  "For whoever has two hoppers: the page shows them side by side, Pellet 1 and Pellet 2, with the same threshold as the first.":
    "İki deposu olanlar için: sayfa onları yan yana gösterir, Pelet 1 ve Pelet 2, ilkiyle aynı eşikle.",
  Ignition: "Ateşleme",
  "In alarm": "Alarm durumunda",
  "Living room stove": "Salon sobası",
  "Lower the power": "Gücü düşür",
  Modulating: "Modülasyon",
  "No stove configured": "Soba tanımlı değil",
  "On its own it covers nearly everything: on and off, the target, the room temperature and, if it has them, the fan modes.":
    "Tek başına neredeyse her şeyi karşılar: açma kapama, hedef, oda sıcaklığı ve varsa fan modları.",
  "Pellet level, second hopper": "Pelet seviyesi, ikinci depo",
  "Pellet OK": "Pelet yeterli",
  "Pellet running low": "Pelet azalıyor",
  "Power level": "Güç seviyesi",
  "Raise the power": "Gücü artır",
  "Roof collectors and a tank: the fields are the ones below.":
    "Çatıda kolektörler ve bir depo: alanlar aşağıdakiler.",
  "Room temperature": "Oda sıcaklığı",
  "Save stove": "Sobayı kaydet",
  "Shutting down": "Kapanıyor",
  "Slow the fan down": "Fanı yavaşlat",
  "Speed the fan up": "Fanı hızlandır",
  Stove: "Soba",
  "Stove alarm": "Soba alarmı",
  "Stove controls": "Soba kontrolleri",
  "Stove phase": "Soba aşaması",
  "Stove thermostat": "Soba termostatı",
  "Switch (when there is no thermostat)": "Anahtar (termostat yoksa)",
  "The stove heats the room it stands in: the page draws the flame, the power, the fan, the flue and the hopper, and gives you the buttons for on and off, the target, the power and the fan. No field is required: with just the thermostat the page already has almost everything. With more than one, add them here and the page grows a row to switch between them.":
    "Soba bulunduğu odayı ısıtır: sayfa alevi, gücü, fanı, bacayı ve depoyu çizer; açma kapama, hedef, güç ve fan düğmelerini verir. Hiçbir alan zorunlu değil: yalnızca termostatla sayfada neredeyse her şey olur. Birden fazlası varsa buraya ekle; sayfada aralarında geçiş için bir sıra belirir.",
  "The word the stove shows on its display: ignition, working, brazier cleaning, shutdown… If the page does not know it, it shows it as it is.":
    "Sobanın ekranında yazan kelime: ateşleme, çalışma, yanma haznesi temizliği, kapanma… Sayfa onu tanımıyorsa olduğu gibi gösterir.",
  "Without it, the thermostat's own reading is used.": "Yoksa termostatın kendi ölçümü kullanılır.",
  Working: "Çalışıyor",
  "Air conditioners out of season": "Sezon dışı klimalar",
  "Radiators out of season": "Sezon dışı radyatörler",
  "They show: ${periodo}. Switched on, they show anyway.":
    "Görünür: ${periodo}. Açık olanlar yine de görünür.",
  "Show them anyway": "Yine de göster",
  "🐠 The aquarium's entities": "🐠 Akvaryumun varlıkları",
  "🦎 The terrarium's entities": "🦎 Teraryumun varlıkları",
  "🧽 Cleaning": "🧽 Temizlik",
  "🪣 The tank": "🪣 Tank",
  Aquariums: "Akvaryumlar",
  "Aquariums and terrariums": "Akvaryumlar ve teraryumlar",
  "Bowl · Litter · Aquariums · Terrariums": "Mama kabı · Kum kabı · Akvaryumlar · Teraryumlar",
  Cats: "Kediler",
  "Clean every (days)": "Temizlik sıklığı (gün)",
  "Cleaned ${giorni} days ago": "${giorni} gün önce temizlendi",
