  "Cleaning due": "Temizlik zamanı",
  Dogs: "Köpekler",
  "Heat lamp or heating": "Isı lambası veya ısıtma",
  "Humidity too high": "Nem çok yüksek",
  "Humidity too low": "Nem çok düşük",
  "Last cleaning": "Son temizlik",
  Mister: "Sisleyici",
  "Not recorded yet: tap “Done today” on the day you clean it, and from then on the card counts the days.":
    "Henüz kaydedilmedi: temizlediğin gün “Bugün yapıldı”ya dokun, kart o andan itibaren günleri sayar.",
  "One row per entity: temperature and pH with their ideal range, the water level, the lights, the filter and the heater. Empty ranges use the defaults: 24–27 °C and pH 6.5–7.5.":
    "Her varlık için bir satır: ideal aralıklarıyla sıcaklık ve pH, su seviyesi, ışıklar, filtre ve ısıtıcı. Boş aralıklar varsayılanları kullanır: 24–27 °C ve pH 6,5–7,5.",
  "One row per entity: warm-side and cool-side temperatures, humidity, lights, heat lamp, UVB, mister. Empty ranges use the defaults: 28–35 °C on the warm side, 22–28 °C on the cool side, humidity 40–80 %.":
    "Her varlık için bir satır: sıcak ve serin taraf sıcaklıkları, nem, ışıklar, ısı lambası, UVB, sisleyici. Boş aralıklar varsayılanları kullanır: sıcak tarafta 28–35 °C, serin tarafta 22–28 °C, nem %40–80.",
  "Optional: left empty, the terrarium reminds nobody to clean it. With a number the card says when it is due.":
    "İsteğe bağlı: boş bırakılırsa teraryum kimseye temizliği hatırlatmaz. Bir sayıyla kart zamanının ne zaman geldiğini söyler.",
  "Other pet": "Diğer hayvan",
  "Other pets": "Diğer hayvanlar",
