  "Warn about open windows": "Açık pencereler için uyar",
  "Who is home": "Evde kim var",
  windy: "rüzgârlı",
  "With GdAHome Base this dashboard stays a normal dashboard. With Premium it becomes a panel for a wall tablet: Room, Scenes or Entrance, landscape and portrait. Premium is turned on from the GdAHome app.":
    "GdAHome Base ile bu panel normal bir panel olarak kalır. Premium ile bir duvar tableti ekranına dönüşür: Oda, Sahneler veya Giriş, yatay ve dikey. Premium, GdAHome uygulamasından açılır.",
  "Wrong code": "Yanlış kod",
  "Yes, go": "Evet, devam",
  "All lights": "Tüm ışıklar",
  "Big button name": "Büyük düğmenin adı",
  "Clear the slot": "Yeri boşalt",
  Drawing: "Çizim",
  "Empty: the entity name": "Boş: varlığın adı",
  "Every light in the house": "Evdeki tüm ışıklar",
  "Front door": "Ön kapı",
  "It fills itself with every light of the source dashboard: a light added there shows up here too.":
    "Kaynak panodaki tüm ışıklarla kendiliğinden dolar: orada eklenen bir ışık burada da görünür.",
  "My page": "Sayfam",
  "None yet": "Henüz yok",
  "Nothing to show here": "Burada gösterilecek bir şey yok",
  "on the tablet": "tablette",
  "or an action": "ya da bir eylem",
  "Second button name": "İkinci düğmenin adı",
  "The page takes its temperature and suggested controls from here":
    "Sayfa sıcaklığını ve önerilen kontrolleri buradan alır",
  "Your own controls": "Kendi kontrollerin",
  "Heating · Cooling": "Isıtma · Soğutma",
  "It fills itself with the source dashboard's climate, split into the Cooling and Heating tabs like the Climate section: air conditioners in cooling, radiators and thermostats in heating, heat pumps in both.":
    "Kaynak panodaki iklimlendirmeyle kendiliğinden dolar; İklim bölümündeki gibi Soğutma ve Isıtma sekmelerine ayrılır: klimalar soğutmada, radyatörler ve termostatlar ısıtmada, ısı pompaları ikisinde de.",
  "Opens on": "Açılış sekmesi",
  "Page type": "Sayfa türü",
  "Shown on the tab at the top": "Üstteki sekmede görünür",
  "The wall tablet's panel. Choose the pages — the tabs at the top — and what each one holds. On the tablet, holding the clock for two seconds brings you back here.":
    "Duvar tabletinin paneli. Sayfaları — üstteki sekmeleri — ve her birinde ne olacağını seç. Tablette saate iki saniye basılı tutmak seni buraya geri getirir.",
  "All blinds": "Tüm panjurlar",
  "At the top and on the rest screen. Empty: the first one Home Assistant has":
    "Üstte ve dinlenme ekranında. Boş: Home Assistant'taki ilki",
  Blinds: "Panjurlar",
  "Choose the readings in the config": "Ölçümleri yapılandırmada seç",
  Duplicate: "Çoğalt",
  "Duplicate page": "Sayfayı çoğalt",
  "Empty: the one of the first page's room": "Boş: ilk sayfanın odasındaki",
  "Every blind in the house": "Evdeki tüm panjurlar",
  "from the dashboard": "panodan",
  "From the grid": "Şebekeden",
  "Grid exchange": "Şebeke alışverişi",
  "House consumption": "Ev tüketimi",
  "House uses": "Ev tüketiyor",
  "How many cards on screen; the rest scroll": "Ekranda kaç kart; gerisi kayar",
  "How many slots, and how big. In portrait columns and rows swap":
    "Kaç yer ve ne büyüklükte. Dikeyde sütunlar ve satırlar yer değiştirir",
  "It fills itself with every blind of the source dashboard: up, stop and down for each one.":
    "Kaynak panodaki tüm panjurlarla kendiliğinden dolar: her biri için yukarı, dur ve aşağı.",
  "Lights off": "Işıklar kapalı",
  "Like the page type": "Sayfa türü gibi",
  "Live pictures": "Canlı görüntüler",
  "Live preview": "Canlı önizleme",
  "No camera in the dashboard": "Panoda kamera yok",
  "No room with sensors or lights": "Sensörlü veya ışıklı oda yok",
  "Of the tab and the title": "Sekmenin ve başlığın",
  "Off, the tablet stays on the page it was on": "Kapalı: tablet bulunduğu sayfada kalır",
  "On rest go back to the first page": "Dinlenmede ilk sayfaya dön",
  "One tile per room, with temperature, humidity and how many lights are on, live. Rooms and their sensors come from the source dashboard.":
    "Her oda için bir kart: sıcaklık, nem ve kaç ışığın açık olduğu, canlı. Odalar ve sensörleri kaynak panodan gelir.",
  "Positive is drawn, negative is fed in": "Pozitif çekilir, negatif verilir",
  "Power, in W or kW": "Güç, W veya kW",
  "Right now, at home": "Şu anda, evde",
  "Solar makes": "Güneş üretiyor",
  "Solar production": "Güneş üretimi",
  "Temperature · Humidity · Lights": "Sıcaklık · Nem · Işıklar",
  "Temperature on the rest screen": "Dinlenme ekranındaki sıcaklık",
  "The source dashboard's cameras, all together; a tap opens one full screen.":
    "Kaynak panonun kameraları, hepsi bir arada; bir dokunuş birini tam ekran açar.",
  "To the grid": "Şebekeye",
  "Unsaved changes: the tablet sees them after «Save».":
    "Kaydedilmemiş değişiklikler: tablet bunları «Kaydet»ten sonra görür.",
  "Empty: the ones from the dashboard's Music section": "Boş: panonun Müzik bölümündekiler",
  "No player: add them in the Music section or here in the config":
    "Oynatıcı yok: Müzik bölümünde veya burada yapılandırmada ekle",
  Players: "Oynatıcılar",
  "The ones chosen here, in this order": "Burada seçilenler, bu sırayla",
  "The player that's playing, big, with cover, buttons, volume and sources; beside it the others, each with its own play. A tap on a player brings it up big.":
    "Çalan oynatıcı büyük, kapak, tuşlar, ses ve kaynaklarla; yanında diğerleri, her birinin kendi oynat tuşu. Bir oynatıcıya dokunmak onu büyük gösterir.",
  "What's playing at home": "Evde ne çalıyor",
  "Grouped with": "Şununla grupta",
  "In the group": "Grupta",
  "Plays together with": "Birlikte çalıyor:",
  "Tap a player to add it to or remove it from the group":
    "Gruba eklemek veya çıkarmak için bir oynatıcıya dokun",
  "Ungroup all": "Grubu dağıt",
  "Full-screen alerts": "Tam ekran uyarılar",
  Press: "Bas",
  "Someone at the door": "Kapı çalıyor",
  "When an alert turns on or the alarm goes off, the panel wakes up and shows it big until someone taps “Got it”":
    "Bir uyarı açıldığında veya alarm çaldığında panel uyanır ve biri «Gördüm» düğmesine dokunana kadar büyük gösterir",
  "When it rings, the panel wakes up and opens the intercom by itself":
    "Zil çaldığında panel uyanır ve diafonu kendiliğinden açar",
  "Tablet battery": "Tablet pili",
  "On the rest screen: how charged it is and whether it is plugged in":
    "Dinlenme ekranında: ne kadar dolu olduğu ve şarja takılı olup olmadığı",
  "For example the battery sensor of the Home Assistant app. Empty: the one the tablet's browser gives":
    "Örneğin Home Assistant uygulamasının pil sensörü. Boş: tabletin tarayıcısının verdiği değer",
  "Optional: the “is charging” sensor or the battery state":
    "İsteğe bağlı: “şarj oluyor” sensörü veya pil durumu",
  Thermostat: "Termostat",
