  "The alarm is going off": "Alarm çalıyor",
  "the car": "arabayı",
  "The house assistant watches the house for you and tells you the most important thing to do right now: lights left on in an empty house, a window open with the heating on, rain on its way, the laundry done, spare solar power. It learns from what you dismiss, and remembers it for the whole household. On a computer or tablet it sits to the right of the people, on a phone below them.":
    "Ev asistanı evi senin yerine izler ve şu an yapılacak en önemli şeyi söyler: boş evde açık kalan ışıklar, ısıtma açıkken açık pencere, yaklaşan yağmur, biten çamaşır, artan güneş enerjisi. Kapattıklarından öğrenir ve bunu tüm hane için hatırlar. Bilgisayar ve tablette kişilerin sağında, telefonda altlarında durur.",
  "The house is drawing ${kw} kW from the grid": "Ev şebekeden ${kw} kW çekiyor",
