  "then → ${allora}": "o zaman → ${allora}",
  "This automation lives in a Home Assistant file: here you turn it on, off and run it, and it is changed there.":
    "Bu otomasyon bir Home Assistant dosyasında: burada açar, kapatır ve çalıştırırsınız, değişikliği orada yapılır.",
  "This automation uses advanced features (a choice between cases, a template, a blueprint…): here you can turn it on and off, run it, rename it and change its room. For the rest:":
    "Bu otomasyon gelişmiş özellikler kullanıyor (durumlar arasında seçim, şablon, blueprint…): burada açıp kapatabilir, çalıştırabilir, yeniden adlandırabilir ve odasını değiştirebilirsiniz. Gerisi için:",
