  "When the apps are in the stores, you turn on Premium from the app and Automations unlock here by themselves.":
    "Uygulamalar mağazalara geldiğinde Premium'u uygulamadan etkinleştirirsiniz ve burada Otomasyonlar kendiliğinden açılır.",
