    "Home Assistant kapı veya pencere kontağını kendisi bildirir ve hiçbir ayar yapmadan burada görünür.",
  "Home Assistant declares a motion or presence sensor itself and it appears here with nothing to configure.":
    "Bir hareket veya varlık sensörünü Home Assistant kendisi bildirir ve hiçbir şey ayarlamadan burada görünür.",
