  "At a glance": "Bir bakışta",
  "At a glance: one page with the weather and big tiles. Each tile opens its data in a popup — the solar flow, live cameras, alarm buttons — and the gate opens with one tap.": "Bir bakışta: hava durumu ve büyük kutucuklardan oluşan tek sayfa. Her kutucuk verilerini bir pencerede açar — güneş akışı, canlı kameralar, alarm düğmeleri — ve kapı tek dokunuşla açılır.",
