  "overtime": "uzatma",
  "shootout": "penaltı atışları",
  "The Sports page: your football or hockey team, Formula 1 and MotoGP, with results, upcoming matches and races, and standings. On Home the tile shows what matters now: the match being played, today's match, the last podium. Results are fetched by the add-on from public sources, only for signed-in users.": "Spor sayfası: futbol veya hokey takımın, Formula 1 ve MotoGP; sonuçlar, yaklaşan maçlar ve yarışlar, puan durumları. Ana sayfada kutucuk şu an önemli olanı gösterir: oynanan maç, bugünkü maç, son podyum. Sonuçları eklenti herkese açık kaynaklardan alır, yalnızca oturum açmış kullanıcılar için.",
  "The team's games, results (live too) and its place in its conference are shown. Italian leagues are not available: they have no public data source.": "Takımın maçları, sonuçları (canlı da) ve konferanstaki yeri gösterilir. İtalyan ligleri yok: herkese açık bir veri kaynakları yok.",
  "✓ Sent: you should hear it now.": "✓ Gönderildi: şimdi duymalısınız.",
  "A sentence on the chosen Echos.": "Seçilen Echo'larda bir cümle.",
  "Announcement": "Duyuru",
  "Announcement: a chime, then the voice. Voice: the voice only.": "Duyuru: önce bir ses, sonra konuşma. Ses: yalnızca konuşma.",
  "Have the Echos say the notifications": "Bildirimleri Echo'lara söylet",
  "How it says it": "Nasıl söyler",
  "Install the «Alexa Media Player» integration from HACS and sign in with your Amazon account: the Echos show up here by themselves.": "HACS'tan «Alexa Media Player» entegrasyonunu kurun ve Amazon hesabınızla giriş yapın: Echo'lar burada kendiliğinden görünür.",
  "No Echo in Home Assistant": "Home Assistant'ta Echo yok",
  "Notifications reach the phones; this way the Echos at home say them too, for whoever is home with their hands full. It applies to the whole home.": "Bildirimler telefonlara gider; böylece evdeki Echo'lar da söyler, evde elleri dolu olanlar için. Tüm ev için geçerlidir.",
  "offline": "çevrimdışı",
  "Only home admins can run the test.": "Testi yalnızca ev yöneticileri yapabilir.",
