  "Your own sentences the Echos say at a time or when something changes at home. Timed ones are said at night too.": "Echo'ların belirli bir saatte ya da evde bir şey değiştiğinde söylediği kendi cümleleriniz. Saatli olanlar gece de söylenir.",
