  "One tap and the same music moves to the chosen Echos: the Echos look it up by title and artist, the previous player pauses.": "Tek dokunuşla aynı müzik seçilen Echo'lara geçer: Echo'lar onu başlık ve sanatçıyla arar, önceki oynatıcı duraklar.",
