  "Remove from favourites": "Favorilerden çıkar",
  "Tap an Echo to choose it. Several Echos play the same music, each on its own: to have it in sync use a speaker group from the Alexa app.": "Seçmek için bir Echo'ya dokun. Birden çok Echo aynı müziği ayrı ayrı çalar: senkron için Alexa uygulamasından bir hoparlör grubu kullan.",
  "To the Echos": "Echo'lara",
