  "A station not in the list: write the name as you would say it to Alexa, the Echos look it up on TuneIn.": "Listede olmayan bir istasyon: adını Alexa'ya söyler gibi yaz, Echo'lar TuneIn'de arar.",
  "Add a station": "İstasyon ekle",
  "Add the «Radio Browser» integration in Home Assistant (Settings › Devices & services › Add integration): it is free and brings thousands of stations.": "Home Assistant'ta «Radio Browser» entegrasyonunu ekle (Ayarlar › Cihazlar ve hizmetler › Entegrasyon ekle): ücretsizdir ve binlerce istasyon getirir.",
  "Echos only": "Yalnızca Echo",
